    public static string AccountSecurity(string email, string role) => """
<!doctype html><html lang="tr"><head><link rel='stylesheet' href='/r129-feedback.css?v=1'><script defer src='/r129-feedback.js?v=1'></script><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Hesap Güvenliği | İnokskar</title><link rel="stylesheet" href="/r104-access.css?v=r14-9"><link rel="stylesheet" href="/r123-professional.css"><script src="/r123-security.js" defer></script><link rel="stylesheet" href="/r13-interface.css?v=r22-clean"><link rel="stylesheet" href="/r13-pages.css?v=r22-2"><link rel="stylesheet" href="/r22-public-shell.css?v=r22-4"><script src="/r13-pages.js?v=logo-navigation-only-3" defer></script></head><body><header class="access-top private-brand-header"><a class="private-brand-link" href="/" aria-label="İNOKSKAR ana sayfa"><img class="private-brand-image" src="/inokskar-header-brand.png" alt="İNOKSKAR Soğutma ve Endüstriyel Mutfak"></a><nav>@@ACCOUNT_NAV@@</nav></header><main class="access-wrap narrow"><section class="access-card"><p class="eyebrow">HESABIM</p><h1>Şifre değiştir</h1><p><strong>@@EMAIL@@</strong> · @@ROLE@@</p><form id="own-password" class="password-form"><label>Mevcut şifre<input name="currentPassword" type="password" required autocomplete="current-password"></label><label>Yeni şifre<input name="newPassword" type="password" minlength="8" maxlength="128" required autocomplete="new-password"></label><label>Yeni şifre tekrar<input name="confirmPassword" type="password" minlength="8" maxlength="128" required autocomplete="new-password"></label><button class="button">Şifreyi değiştir</button><p id="own-password-note"></p></form></section></main><script>document.getElementById('own-password').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,n=document.getElementById('own-password-note');const b={currentPassword:f.currentPassword.value,newPassword:f.newPassword.value,confirmPassword:f.confirmPassword.value};if(b.newPassword!==b.confirmPassword){n.textContent='Yeni şifreler aynı değil.';return;}const r=await fetch('/api/account/password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});const j=await r.json().catch(()=>({}));if(!r.ok){n.textContent=j.error||'Şifre değiştirilemedi.';return;}location.href='/login?reset=1';});</script></body></html>
""".Replace("@@EMAIL@@", System.Net.WebUtility.HtmlEncode(email), StringComparison.Ordinal).Replace("@@ROLE@@", System.Net.WebUtility.HtmlEncode(role), StringComparison.Ordinal).Replace("@@ACCOUNT_NAV@@", role=="Customer"?"<a href='/hesabim/profil'>← Hesabıma dön</a><a href='/'>Siteye dön</a>":"<a href='/admin'>Yönetim</a><a href='/teknik'>Teknik Servis</a>", StringComparison.Ordinal);
}
